class Solution:
    def canConstructUniformArray(self, nums1):
        n = len(nums1)
        for p in (0, 1):
            ok = True
            for i in range(n):
                if nums1[i] % 2 == p:
                    continue
                if not any((nums1[i] + nums1[j]) % 2 == p for j in range(n) if j != i):
                    ok = False
                    break
            if ok:
                return True
        return False

