class Solution {
public:
    bool canConstructUniformArray(vector<int>& nums1) {
        int n = nums1.size();
        for (int p = 0; p < 2; p++) {
            bool ok = true;
            for (int i = 0; i < n && ok; i++) {
                if (nums1[i] % 2 == p) continue;
                bool found = false;
                for (int j = 0; j < n; j++)
                    if (j != i && (nums1[i] + nums1[j]) % 2 == p) { found = true; break; }
                if (!found) ok = false;
            }
            if (ok) return true;
        }
        return false;
    }
};

